ss,'"epoleodomia"."pd_protection_zones"'::regclass,'"epoleodomia"."pedestrian_zones"'::regclass,'"epoleodomia"."planning_diagrams"'::regclass,'"epoleodomia"."planning_lines"'::regclass,'"epoleodomia"."protected_buildings"'::regclass,'"epoleodomia"."protection_zones_lines"'::regclass,'"epoleodomia"."protection_zones_points"'::regclass,'"epoleodomia"."protection_zones_polygons"'::regclass,'"epoleodomia"."public_spaces"'::regclass,'"epoleodomia"."raster_catalog"'::regclass,'"epoleodomia"."settlement_boundaries"'::regclass,'"epoleodomia"."settlements_2021"'::regclass,'"epoleodomia"."shorelines"'::regclass,'"epoleodomia"."streams"'::regclass,'"epoleodomia"."streams_environmental"'::regclass,'"epoleodomia"."sync_log"'::regclass,'"epoleodomia"."sync_runs"'::regclass,'"epoleodomia"."urban_units"'::regclass,'"epoleodomia"."zoe_zones"'::regclass,'"sp_geodata"."kaek_apokleistikes_operating"'::regclass,'"sp_geodata"."kaek_douleies_operating"'::regclass,'"sp_geodata"."kaek_parcels_operating"'::regclass,'"sp_geodata"."ydrolipsies_emsy"'::regclass)
